#!/bin/bash
# Generates 10 Sanad hero-template directions. ponytail: one throwaway script, delete after picking.
G="/Users/soudi/.claude/plugins/cache/ibrahim-plugins/nano-banana/2.1.0/scripts/genimage.py"
OUT="/Users/soudi/Sanad Marketing production 08.26/templates"
BRAND="Brand palette strictly: deep pine green #0C3B2E, muted gold #C9A24B, warm paper cream #F7F3EA, ink #10241E. Wordmark reads 'Sanad' in latin next to the Arabic word 'سند', with a small rounded square mark containing the Arabic letter 'س'. Top navigation links read 'How it works', 'Security', 'Pricing', 'FAQ' plus a small pill button reading 'عربي'. No stock photos of people, no medical or dental imagery, no syringes, no teeth, no doctors. No neon, no purple, no pink."

run () { python3 "$G" --prompt "$2" --output "$OUT/$1.png" --aspect-ratio 16:9 --resolution 2K > "$OUT/$1.log" 2>&1 & }

run 01-chrome-obsidian "Website hero section screenshot, desktop 16:9, for a B2B AI product. Near-black obsidian background. A large glossy chrome and frosted-glass 3D sculpture of a curved ribbon and floating capsule forms bleeds diagonally across the lower two thirds, lit with cool studio highlights and small warm gold light leaks. Enormous bold grotesk headline in two lines, tight tracking, centered: first line in white reading 'Your patients send voice notes.', second line in a soft gold-to-cream gradient reading 'Sanad listens and books them.' Below it a single line of small grey subtext reading 'Voice-first WhatsApp reception for Dubai dental and aesthetics clinics — 24/7, Arabic and English.' Two side-by-side outlined pill buttons with thin gold borders reading 'Book a demo' and 'Founding pricing'. Thin top navigation bar. At the very bottom edge, a faint horizontal marquee strip of repeating small text and a downward arrow. $BRAND"

run 02-pine-editorial "Website hero section screenshot, desktop 16:9. Deep pine green #0C3B2E full-bleed background with a subtle warm gold radial glow rising from the bottom. Two column layout. Left column: a small gold pill badge reading 'Dubai dental and aesthetics · 10 founding clinics · 40% off setup', then a very large elegant high-contrast serif headline in cream reading 'Your patients send voice notes. Sanad listens and books them.' with the words 'voice notes' underlined by a thick soft gold highlight bar, a short paragraph of muted sage body text below, and two buttons: a solid gold button reading 'See it on your own phone' and a ghost outlined cream button reading 'Founding pricing'. Right column: a realistic floating white smartphone mockup showing a WhatsApp chat, a green outgoing voice-note bubble with a waveform, and Arabic reply bubbles, with a small dark pill caption underneath reading 'Replied in seconds · booked at 9:48 PM'. Refined, calm, editorial, luxury SaaS. $BRAND"

